import{_ as d,o as e,c as a,l as r,t as n,N as s}from"./chunks/framework.Gjrf2Eoj.js";const f=JSON.parse('{"title":"stty | x-cmd man (man1) | change and print terminal line settings","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | stty - change and print terminal line settings","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"stty | x-cmd man (man1) | change and print terminal line settings"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | stty - change and print terminal line settings"}]]},"headers":[],"params":{"isMan":true,"man":"stty","category":"man1","desc":"change and print terminal line settings"},"relativePath":"man1/stty.md","filePath":"man1/stty.md"}'),o={name:"man1/stty.md"},i={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>stty - change and print terminal line settings</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>stty</strong> [<em>-F DEVICE | --file=DEVICE</em>] [<em>SETTING</em>]... <br> <strong>stty</strong> [<em>-F DEVICE | --file=DEVICE</em>] [<em>-a|--all</em>] <br> <strong>stty</strong> [<em>-F DEVICE | --file=DEVICE</em>] [<em>-g|--save</em>]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Print or change terminal characteristics.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong>, <strong>--all</strong></dt><dd>print all current settings in human-readable form</dd><dt><strong>-g</strong>, <strong>--save</strong></dt><dd>print all current settings in a stty-readable form</dd><dt><strong>-F</strong>, <strong>--file</strong>=<em>DEVICE</em></dt><dd>open and use the specified DEVICE instead of stdin</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Optional - before SETTING indicates negation. An * marks non-POSIX settings. The underlying system defines which settings are available.</p><h3 id="special-characters" tabindex="-1">Special characters: <a class="header-anchor" href="#special-characters" aria-label="Permalink to &quot;Special characters:&quot;">​</a></h3><dl><dt>* discard CHAR</dt><dd>CHAR will toggle discarding of output</dd><dt>eof CHAR</dt><dd>CHAR will send an end of file (terminate the input)</dd><dt>eol CHAR</dt><dd>CHAR will end the line</dd><dt>* eol2 CHAR</dt><dd>alternate CHAR for ending the line</dd><dt>erase CHAR</dt><dd>CHAR will erase the last character typed</dd><dt>intr CHAR</dt><dd>CHAR will send an interrupt signal</dd><dt>kill CHAR</dt><dd>CHAR will erase the current line</dd><dt>* lnext CHAR</dt><dd>CHAR will enter the next character quoted</dd><dt>quit CHAR</dt><dd>CHAR will send a quit signal</dd><dt>* rprnt CHAR</dt><dd>CHAR will redraw the current line</dd><dt>start CHAR</dt><dd>CHAR will restart the output after stopping it</dd><dt>stop CHAR</dt><dd>CHAR will stop the output</dd><dt>susp CHAR</dt><dd>CHAR will send a terminal stop signal</dd><dt>* swtch CHAR</dt><dd>CHAR will switch to a different shell layer</dd><dt>* werase CHAR</dt><dd>CHAR will erase the last word typed</dd></dl><h3 id="special-settings" tabindex="-1">Special settings: <a class="header-anchor" href="#special-settings" aria-label="Permalink to &quot;Special settings:&quot;">​</a></h3><dl><dt>N</dt><dd>set the input and output speeds to N bauds</dd><dt>* cols N</dt><dd>tell the kernel that the terminal has N columns</dd><dt>* columns N</dt><dd>same as cols N</dd><dt>* [-]drain</dt><dd>wait for transmission before applying settings (on by default)</dd><dt>ispeed N</dt><dd>set the input speed to N</dd><dt>* line N</dt><dd>use line discipline N</dd><dt>min N</dt><dd>with <strong>-icanon</strong>, set N characters minimum for a completed read</dd><dt>ospeed N</dt><dd>set the output speed to N</dd><dt>* rows N</dt><dd>tell the kernel that the terminal has N rows</dd><dt>* size</dt><dd>print the number of rows and columns according to the kernel</dd><dt>speed</dt><dd>print the terminal speed</dd><dt>time N</dt><dd>with <strong>-icanon</strong>, set read timeout of N tenths of a second</dd></dl><h3 id="control-settings" tabindex="-1">Control settings: <a class="header-anchor" href="#control-settings" aria-label="Permalink to &quot;Control settings:&quot;">​</a></h3><dl><dt>[-]clocal</dt><dd>disable modem control signals</dd><dt>[-]cread</dt><dd>allow input to be received</dd><dt>* [-]crtscts</dt><dd>enable RTS/CTS handshaking</dd><dt>csN</dt><dd>set character size to N bits, N in [5..8]</dd><dt>[-]cstopb</dt><dd>use two stop bits per character (one with &#39;-&#39;)</dd><dt>[-]hup</dt><dd>send a hangup signal when the last process closes the tty</dd><dt>[-]hupcl</dt><dd>same as [-]hup</dd><dt>[-]parenb</dt><dd>generate parity bit in output and expect parity bit in input</dd><dt>[-]parodd</dt><dd>set odd parity (or even parity with &#39;-&#39;)</dd><dt>* [-]cmspar</dt><dd>use &quot;stick&quot; (mark/space) parity</dd></dl><h3 id="input-settings" tabindex="-1">Input settings: <a class="header-anchor" href="#input-settings" aria-label="Permalink to &quot;Input settings:&quot;">​</a></h3><dl><dt>[-]brkint</dt><dd>breaks cause an interrupt signal</dd><dt>[-]icrnl</dt><dd>translate carriage return to newline</dd><dt>[-]ignbrk</dt><dd>ignore break characters</dd><dt>[-]igncr</dt><dd>ignore carriage return</dd><dt>[-]ignpar</dt><dd>ignore characters with parity errors</dd><dt>* [-]imaxbel</dt><dd>beep and do not flush a full input buffer on a character</dd><dt>[-]inlcr</dt><dd>translate newline to carriage return</dd><dt>[-]inpck</dt><dd>enable input parity checking</dd><dt>[-]istrip</dt><dd>clear high (8th) bit of input characters</dd><dt>* [-]iutf8</dt><dd>assume input characters are UTF-8 encoded</dd><dt>* [-]iuclc</dt><dd>translate uppercase characters to lowercase</dd><dt>* [-]ixany</dt><dd>let any character restart output, not only start character</dd><dt>[-]ixoff</dt><dd>enable sending of start/stop characters</dd><dt>[-]ixon</dt><dd>enable XON/XOFF flow control</dd><dt>[-]parmrk</dt><dd>mark parity errors (with a 255-0-character sequence)</dd><dt>[-]tandem</dt><dd>same as [-]ixoff</dd></dl><h3 id="output-settings" tabindex="-1">Output settings: <a class="header-anchor" href="#output-settings" aria-label="Permalink to &quot;Output settings:&quot;">​</a></h3><dl><dt>* bsN</dt><dd>backspace delay style, N in [0..1]</dd><dt>* crN</dt><dd>carriage return delay style, N in [0..3]</dd><dt>* ffN</dt><dd>form feed delay style, N in [0..1]</dd><dt>* nlN</dt><dd>newline delay style, N in [0..1]</dd><dt>* [-]ocrnl</dt><dd>translate carriage return to newline</dd><dt>* [-]ofdel</dt><dd>use delete characters for fill instead of NUL characters</dd><dt>* [-]ofill</dt><dd>use fill (padding) characters instead of timing for delays</dd><dt>* [-]olcuc</dt><dd>translate lowercase characters to uppercase</dd><dt>* [-]onlcr</dt><dd>translate newline to carriage return-newline</dd><dt>* [-]onlret</dt><dd>newline performs a carriage return</dd><dt>* [-]onocr</dt><dd>do not print carriage returns in the first column</dd><dt>[-]opost</dt><dd>postprocess output</dd><dt>* tabN</dt><dd>horizontal tab delay style, N in [0..3]</dd><dt>* tabs</dt><dd>same as tab0</dd><dt>* <strong>-tabs</strong></dt><dd>same as tab3</dd><dt>* vtN</dt><dd>vertical tab delay style, N in [0..1]</dd></dl><h3 id="local-settings" tabindex="-1">Local settings: <a class="header-anchor" href="#local-settings" aria-label="Permalink to &quot;Local settings:&quot;">​</a></h3><dl><dt>[-]crterase</dt><dd>echo erase characters as backspace-space-backspace</dd><dt>* crtkill</dt><dd>kill all line by obeying the echoprt and echoe settings</dd><dt>* <strong>-crtkill</strong></dt><dd>kill all line by obeying the echoctl and echok settings</dd><dt>* [-]ctlecho</dt><dd>echo control characters in hat notation (&#39;^c&#39;)</dd><dt>[-]echo</dt><dd>echo input characters</dd><dt>* [-]echoctl</dt><dd>same as [-]ctlecho</dd><dt>[-]echoe</dt><dd>same as [-]crterase</dd><dt>[-]echok</dt><dd>echo a newline after a kill character</dd><dt>* [-]echoke</dt><dd>same as [-]crtkill</dd><dt>[-]echonl</dt><dd>echo newline even if not echoing other characters</dd><dt>* [-]echoprt</dt><dd>echo erased characters backward, between &#39;\\&#39; and &#39;/&#39;</dd><dt>* [-]extproc</dt><dd>enable &quot;LINEMODE&quot;; useful with high latency links</dd><dt>* [-]flusho</dt><dd>discard output</dd><dt>[-]icanon</dt><dd>enable special characters: erase, kill, werase, rprnt</dd><dt>[-]iexten</dt><dd>enable non-POSIX special characters</dd><dt>[-]isig</dt><dd>enable interrupt, quit, and suspend special characters</dd><dt>[-]noflsh</dt><dd>disable flushing after interrupt and quit special characters</dd><dt>* [-]prterase</dt><dd>same as [-]echoprt</dd><dt>* [-]tostop</dt><dd>stop background jobs that try to write to the terminal</dd><dt>* [-]xcase</dt><dd>with icanon, escape with &#39;\\&#39; for uppercase characters</dd></dl><h3 id="combination-settings" tabindex="-1">Combination settings: <a class="header-anchor" href="#combination-settings" aria-label="Permalink to &quot;Combination settings:&quot;">​</a></h3><dl><dt>* [-]LCASE</dt><dd>same as [-]lcase</dd><dt>cbreak</dt><dd>same as <strong>-icanon</strong></dd><dt><strong>-cbreak</strong></dt><dd>same as icanon</dd><dt>cooked</dt><dd>same as brkint ignpar istrip icrnl ixon opost isig icanon, eof and eol characters to their default values</dd><dt><strong>-cooked</strong></dt><dd>same as raw</dd><dt>crt</dt><dd>same as echoe echoctl echoke</dd><dt>dec</dt><dd>same as echoe echoctl echoke <strong>-ixany</strong> intr ^c erase 0177 kill ^u</dd><dt>* [-]decctlq</dt><dd>same as [-]ixany</dd><dt>ek</dt><dd>erase and kill characters to their default values</dd><dt>evenp</dt><dd>same as parenb <strong>-parodd</strong> cs7</dd><dt><strong>-evenp</strong></dt><dd>same as <strong>-parenb</strong> cs8</dd><dt>* [-]lcase</dt><dd>same as xcase iuclc olcuc</dd><dt>litout</dt><dd>same as <strong>-parenb</strong> <strong>-istrip</strong> <strong>-opost</strong> cs8</dd><dt><strong>-litout</strong></dt><dd>same as parenb istrip opost cs7</dd><dt>nl</dt><dd>same as <strong>-icrnl</strong> <strong>-onlcr</strong></dd><dt><strong>-nl</strong></dt><dd>same as icrnl <strong>-inlcr</strong> <strong>-igncr</strong> onlcr <strong>-ocrnl</strong> <strong>-onlret</strong></dd><dt>oddp</dt><dd>same as parenb parodd cs7</dd><dt><strong>-oddp</strong></dt><dd>same as <strong>-parenb</strong> cs8</dd><dt>[-]parity</dt><dd>same as [-]evenp</dd><dt>pass8</dt><dd>same as <strong>-parenb</strong> <strong>-istrip</strong> cs8</dd><dt><strong>-pass8</strong></dt><dd>same as parenb istrip cs7</dd><dt>raw</dt><dd>same as <strong>-ignbrk</strong> <strong>-brkint</strong> <strong>-ignpar</strong> <strong>-parmrk</strong> <strong>-inpck</strong><strong>-istrip</strong> <strong>-inlcr</strong> <strong>-igncr</strong> <strong>-icrnl</strong> <strong>-ixon</strong> <strong>-ixoff</strong><strong>-icanon</strong> <strong>-opost</strong> <strong>-isig</strong> <strong>-iuclc</strong> <strong>-ixany</strong> <strong>-imaxbel</strong><strong>-xcase</strong> min 1 time 0</dd><dt><strong>-raw</strong></dt><dd>same as cooked</dd><dt>sane</dt><dd>same as cread <strong>-ignbrk</strong> brkint <strong>-inlcr</strong> <strong>-igncr</strong> icrnl icanon iexten echo echoe echok <strong>-echonl</strong> <strong>-noflsh</strong> <strong>-ixoff</strong><strong>-iutf8</strong> <strong>-iuclc</strong> <strong>-ixany</strong> imaxbel <strong>-xcase</strong> <strong>-olcuc</strong><strong>-ocrnl</strong> opost <strong>-ofill</strong> onlcr <strong>-onocr</strong> <strong>-onlret</strong> nl0 cr0 tab0 bs0 vt0 ff0 isig <strong>-tostop</strong> <strong>-ofdel</strong> <strong>-echoprt</strong> echoctl echoke <strong>-extproc</strong> <strong>-flusho</strong>, all special characters to their default values</dd></dl><p>Handle the tty line connected to standard input. Without arguments, prints baud rate, line discipline, and deviations from stty sane. In settings, CHAR is taken literally, or coded as in ^c, 0x37, 0177 or 127; special values ^- or undef used to disable special characters.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/stty%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/stty\\</a>&gt; <br> or available locally via: info &#39;(coreutils) stty invocation&#39;</p>',32);function c(t,g,h,p,u,m){return e(),a("div",null,[r("h1",i,n(t.$params.man),1),l])}const y=d(o,[["render",c]]);export{f as __pageData,y as default};
